    faqPage: {
      eyebrow: "Frequently asked questions",
      title: "FAQ",
      description:
        "Answers to the most common questions about using SearchTalent — accounts, profiles, projects, and more.",
      backToHome: "Back to home",
      items: [
        {
          q: "Is SearchTalent free to use?",
          a: "Yes. Creating an account, building a profile, and publishing projects is completely free.",
        },
        {
          q: "How do I create a public profile?",
          a: "Sign up, open your space, and fill in your profile details — name, skills, experience, and contacts. Once you set a username, your public page becomes available.",
        },
        {
          q: "Can I find work or hire people here?",
          a: "Yes. You mark on your page what you are open to (freelance, a job, an internship, collaboration or mentoring), and people reach you through the “Contact” button. Companies create free pages with their team and its work. Your email and phone are shown only to signed-in people who press the button; you agree on everything directly.",
        },
        {
          q: "Can I publish multiple projects?",
          a: "Absolutely. There is no limit on the number of projects you can publish. Each project gets its own public page with media, description, and community votes.",
        },
        {
          q: "Can I write articles?",
          a: "Yes. Besides projects, you can publish articles from your space — write-ups, tutorials, or opinion pieces with rich formatting, images, and GIFs. Published articles appear in the Community section and on your public profile, and they count toward your contribution to the platform.",
        },
        {
          q: "What are polls?",
          a: "Polls let you ask the community a question — single-choice, multiple-choice, or a rating scale. Anyone can read the results, and signed-in members can cast their vote. Create one from your space and it shows up in the Community section.",
        },
        {
          q: "Can I collaborate with others?",
          a: "Yes. When creating a project, article, or poll you can invite other members as co-authors. Each invited person confirms via notifications, and the work is published once everyone agrees. Co-authors are credited on the public page.",
        },
        {
          q: "How does the rating system work?",
          a: "Community members can upvote or downvote profiles and projects. The ranking factors in project depth, profile completeness, community response (using a Wilson score), recent activity with time decay, and earned badges. For the full breakdown of factors and weights, see the rating guide.",
        },
        {
          q: "What are badges and how do I earn them?",
          a: "Badges are awarded automatically for your activity and achievements — publishing your first project, completing your profile, verifying your email or GitHub, reaching the leaderboards, and more. They come in four categories with up to three tiers each, and together they can add up to +5 bonus points to your rating.",
        },
        {
          q: "Can I export my profile?",
          a: "Yes. You can download your profile as a PDF resume directly from your public profile page.",
        },
        {
          q: "How do I report inappropriate content?",
          a: "Use the feedback page to report any content that violates the platform guidelines, and our moderation team reviews reports promptly. Content is also checked automatically when published — anything that trips our rules is placed under review before it appears publicly.",
        },
        {
          q: "What languages are supported?",
          a: "The platform is available in English and Ukrainian. You can switch the language at any time from the header.",
        },
        {
          q: "How do I delete my account?",
          a: "Open your profile settings and use the \"Delete my account\" button at the bottom of the page. We will email you a confirmation code that is valid for 5 minutes. Before confirming, you can choose whether to delete everything — your profile, projects, articles, and comments are removed permanently — or to keep your articles and comments as anonymous content attributed to \"Deleted user\" while the rest of your account is removed. Either way, your profile, projects, votes, likes, and saved data are always deleted, and the action cannot be undone.",
        },
      ],
    },
